package dev.veltraph.client.farming.movement;
import dev.veltraph.client.world.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
/** Pure control observations only; these authored cases are not native jump or input receipts. */
class SupplementalWaterCoverageTest {
 static final SupplementalWaterCoverage.Plan PLAN=new SupplementalWaterCoverage.Plan(new Vec3(50.5,70,-46.5),new Vec3(55.5,70,-46.5),new Vec3(55.5,71,-45.5),new Vec3(55.5,70,-44.5),new Vec3(55.5,70,46.5),Direction.SOUTH,Direction.EAST);
 static final class Model implements SupplementalWaterCoverage.World,SupplementalWaterCoverage.MovementPort {
  Vec3 feet=PLAN.primaryEnd(),target;boolean ground=true,wet,current=true,clear=true,jump,attack;int releases,writes;Runnable currentRead,moveCallback,positionRead;boolean failGroundRead;int currentReads,groundReads,wetReads,bodyReads;SupplementalWaterCoverage.Plan accepted=PLAN;
  public Vec3 position(){if(positionRead!=null){var callback=positionRead;positionRead=null;callback.run();}return feet;}public boolean onGround(){groundReads++;if(failGroundRead)throw new AssertionError("Later stale ground getter invoked");return ground;}public boolean inWater(){wetReads++;return wet;}public boolean current(SupplementalWaterCoverage.Plan p){currentReads++;if(currentRead!=null){var callback=currentRead;currentRead=null;callback.run();}return current&&p==accepted;}public boolean bodyClear(Vec3 p,boolean water){bodyReads++;return clear;}
  public void toward(Vec3 target,boolean jump,boolean attack){this.target=target;this.jump=jump;this.attack=attack;writes++;if(moveCallback!=null){var callback=moveCallback;moveCallback=null;callback.run();}}
  public void release(){jump=attack=false;releases++;}
  void at(Vec3 feet,boolean ground,boolean wet){this.feet=feet;this.ground=ground;this.wet=wet;}
 }
 static SupplementalWaterCoverage started(Model m){var c=new SupplementalWaterCoverage(m,m);assertTrue(c.start(PLAN));return c;}
 static void toJump(Model m,SupplementalWaterCoverage c){m.at(PLAN.approachFeet(),true,false);assertEquals(SupplementalWaterCoverage.State.JUMP_CAP,c.tick());}
 static void toWater(Model m,SupplementalWaterCoverage c){toJump(m,c);c.tick();assertTrue(m.jump);m.at(new Vec3(55.5,70.5,-46.0),false,false);c.tick();assertFalse(m.jump);m.at(PLAN.capFeet(),true,false);assertEquals(SupplementalWaterCoverage.State.ENTER_CHANNEL,c.tick());m.at(PLAN.channelNear(),true,true);assertEquals(SupplementalWaterCoverage.State.SWEEP_OUT,c.tick());}
 @Test void rejectsUnknownInitialGeometry(){var m=new Model();m.current=false;assertFalse(new SupplementalWaterCoverage(m,m).start(PLAN));assertEquals(0,m.writes);}
 @Test void rejectsUnobservedInitialFloor(){var m=new Model();m.ground=false;assertFalse(new SupplementalWaterCoverage(m,m).start(PLAN));}
 @Test void keepsApproachAtOriginalDryFloor(){var m=new Model();var c=started(m);c.tick();assertEquals(PLAN.approachFeet(),m.target);assertFalse(m.jump);assertTrue(m.attack);}
 @Test void requiresRealAirborneObservationBeforeDryCapLanding(){var m=new Model();var c=started(m);toJump(m,c);c.tick();m.at(PLAN.capFeet(),true,false);assertEquals(SupplementalWaterCoverage.State.BLOCKED,c.tick());assertFalse(m.jump);}
 @Test void clearsJumpImmediatelyAfterObservedTakeoff(){var m=new Model();var c=started(m);toJump(m,c);c.tick();assertTrue(m.jump);m.at(new Vec3(55.5,70.5,-46),false,false);c.tick();assertFalse(m.jump);}
 @Test void unknownGeometryDuringJumpReleasesAllRequestedInputs(){var m=new Model();var c=started(m);toJump(m,c);c.tick();m.current=false;assertEquals(SupplementalWaterCoverage.State.BLOCKED,c.tick());assertFalse(m.jump);assertFalse(m.attack);}
 @Test void refusesFarmlandSideDrift(){var m=new Model();var c=started(m);toWater(m,c);m.at(new Vec3(55.71,70,-40),true,true);assertEquals(SupplementalWaterCoverage.State.BLOCKED,c.tick());assertFalse(m.attack);}
 @Test void doesNotTreatUnknownAirAsSupportedWater(){var m=new Model();var c=started(m);toWater(m,c);m.at(new Vec3(55.5,70.2,-40),false,false);assertEquals(SupplementalWaterCoverage.State.BLOCKED,c.tick());}
 @Test void nativeWaterExitRequestsJumpOnlyWhileWet(){var m=new Model();var c=started(m);toWater(m,c);m.at(PLAN.channelFar(),true,true);c.tick();m.at(PLAN.channelNear(),true,true);c.tick();assertEquals(SupplementalWaterCoverage.State.JUMP_EXIT,c.state());c.tick();assertTrue(m.jump);m.at(new Vec3(55.5,71.05,-45.5),false,false);c.tick();assertFalse(m.jump);}
 @Test void returnsViaCapAndDryPortalBeforeSamePrimaryEnd(){var m=new Model();var c=started(m);toWater(m,c);m.at(PLAN.channelFar(),true,true);c.tick();m.at(PLAN.channelNear(),true,true);c.tick();c.tick();m.at(PLAN.capFeet(),true,false);c.tick();assertEquals(SupplementalWaterCoverage.State.RETURN_PRIMARY,c.state());c.tick();assertEquals(PLAN.approachFeet(),m.target);m.at(PLAN.approachFeet(),true,false);c.tick();m.at(PLAN.primaryEnd(),true,false);assertEquals(SupplementalWaterCoverage.State.COMPLETE,c.tick());assertFalse(c.active());assertFalse(m.jump);assertFalse(m.attack);}
 @Test void originalEndRequiresOriginalArrivalHeight(){var m=new Model();var c=started(m);toWater(m,c);m.at(PLAN.channelFar(),true,true);c.tick();m.at(PLAN.channelNear(),true,true);c.tick();c.tick();m.at(PLAN.capFeet(),true,false);c.tick();m.at(PLAN.approachFeet(),true,false);c.tick();m.at(new Vec3(50.5,70.03,-46.5),true,false);assertNotEquals(SupplementalWaterCoverage.State.COMPLETE,c.tick());}
 @Test void pausePreservesPhaseButReleasesJump(){var m=new Model();var c=started(m);toJump(m,c);c.tick();var before=c.maintenanceState();c.pause();assertFalse(m.jump);assertEquals(before,c.maintenanceState());}
 @Test void stopCancelsPlanAndEveryRequestedKey(){var m=new Model();var c=started(m);toJump(m,c);c.tick();c.stop();assertNull(c.plan());assertEquals(SupplementalWaterCoverage.State.IDLE,c.state());assertFalse(m.jump);assertFalse(m.attack);}
 @Test void capAndApproachWaitAreBounded(){var m=new Model();var c=started(m);for(int i=0;i<=160;i++)c.tick();assertEquals(SupplementalWaterCoverage.State.BLOCKED,c.state());assertFalse(m.attack);}
 @Test void stopDuringWorldReadCannotPublishOldMovement(){var m=new Model();var c=started(m);int writes=m.writes;m.currentRead=c::stop;assertEquals(SupplementalWaterCoverage.State.IDLE,c.tick());assertEquals(writes,m.writes);assertNull(c.plan());}
 @Test void replacementDuringWorldReadRetiresOnlyOldFrame(){var m=new Model();var c=started(m);var replacement=new SupplementalWaterCoverage.Plan(PLAN.primaryEnd(),PLAN.approachFeet(),PLAN.capFeet(),PLAN.channelNear(),PLAN.channelFar(),PLAN.inward(),PLAN.harvestHeading());m.currentRead=()->{c.stop();m.accepted=replacement;assertTrue(c.start(replacement));};int writes=m.writes;c.tick();assertSame(replacement,c.plan());assertEquals(SupplementalWaterCoverage.State.APPROACH,c.state());assertEquals(writes,m.writes);}
 @Test void movementCallbackStopCannotBeOverwrittenByOldPhase(){var m=new Model();var c=started(m);m.moveCallback=c::stop;c.tick();assertNull(c.plan());assertEquals(SupplementalWaterCoverage.State.IDLE,c.state());}
 @Test void recursiveTickDuringReadHasNoPositiveEffect(){var m=new Model();var c=started(m);int writes=m.writes;m.currentRead=c::tick;c.tick();assertEquals(writes,m.writes);}

 @Test void firstTickGetterStopSkipsAllLaterThrowingOrSideEffectReads(){var m=new Model();var c=started(m);int current=m.currentReads,ground=m.groundReads,wet=m.wetReads,body=m.bodyReads;m.positionRead=c::stop;m.failGroundRead=true;assertEquals(SupplementalWaterCoverage.State.IDLE,c.tick());assertEquals(current,m.currentReads);assertEquals(ground,m.groundReads);assertEquals(wet,m.wetReads);assertEquals(body,m.bodyReads);}
 @Test void firstTickGetterReplacementSkipsAllRemainingOldReads(){var m=new Model();var c=started(m);var replacement=new SupplementalWaterCoverage.Plan(PLAN.primaryEnd(),PLAN.approachFeet(),PLAN.capFeet(),PLAN.channelNear(),PLAN.channelFar(),PLAN.inward(),PLAN.harvestHeading());int[] after=new int[4];m.positionRead=()->{c.stop();m.accepted=replacement;assertTrue(c.start(replacement));after[0]=m.currentReads;after[1]=m.groundReads;after[2]=m.wetReads;after[3]=m.bodyReads;m.failGroundRead=true;};assertEquals(SupplementalWaterCoverage.State.APPROACH,c.tick());assertSame(replacement,c.plan());assertArrayEquals(after,new int[]{m.currentReads,m.groundReads,m.wetReads,m.bodyReads});}
 @Test void firstStartGetterStopSkipsAllLaterReads(){var m=new Model();var c=new SupplementalWaterCoverage(m,m);m.positionRead=c::stop;m.failGroundRead=true;assertFalse(c.start(PLAN));assertEquals(0,m.currentReads);assertEquals(0,m.groundReads);assertEquals(0,m.wetReads);assertEquals(0,m.bodyReads);}

 @Test void quiesceDuringFirstWorldReadRetiresHelperWithoutNativeCleanup(){var m=new Model();var c=started(m);long generation=c.generation();int releases=m.releases,writes=m.writes,current=m.currentReads,ground=m.groundReads,wet=m.wetReads,body=m.bodyReads;m.positionRead=c::quiesce;m.failGroundRead=true;assertEquals(SupplementalWaterCoverage.State.IDLE,c.tick());assertEquals(generation+1,c.generation());assertNull(c.plan());assertEquals(releases,m.releases);assertEquals(writes,m.writes);assertArrayEquals(new int[]{current,ground,wet,body},new int[]{m.currentReads,m.groundReads,m.wetReads,m.bodyReads});}
 @Test void quiesceHasNoNativeEffectsAndNewPlanNeedsFreshStart(){var m=new Model();var c=started(m);int releases=m.releases,writes=m.writes;c.quiesce();c.tick();assertEquals(releases,m.releases);assertEquals(writes,m.writes);assertTrue(c.start(PLAN));assertSame(PLAN,c.plan());}

 static void airborneBeforeCap(Model m,SupplementalWaterCoverage c){toJump(m,c);c.tick();assertTrue(m.jump);m.at(new Vec3(55.5,70.5,-46.0),false,false);c.tick();}
 static Vec3 safeCapCorner(){return new Vec3(PLAN.capFeet().x()+.17,PLAN.capFeet().y(),PLAN.capFeet().z()+.19);}
 @Test void supportedCapCornerCentersWithoutJumpOrAttackThenUsesOriginalArrivalGate(){var m=new Model();var c=started(m);airborneBeforeCap(m,c);m.at(safeCapCorner(),true,false);assertTrue(m.feet.horizontalDistanceTo(PLAN.capFeet())>.18);assertEquals(SupplementalWaterCoverage.State.JUMP_CAP,c.tick());assertEquals(PLAN.capFeet(),m.target);assertFalse(m.jump);assertFalse(m.attack);m.at(PLAN.capFeet(),true,false);assertEquals(SupplementalWaterCoverage.State.ENTER_CHANNEL,c.tick());}
 @Test void wrongCapHeightCannotBecomeCenteringPermission(){var m=new Model();var c=started(m);airborneBeforeCap(m,c);m.at(new Vec3(55.67,70.9375,-45.31),true,false);assertEquals(SupplementalWaterCoverage.State.BLOCKED,c.tick());assertFalse(m.jump);assertFalse(m.attack);}
 @Test void wetLandingCannotBecomeDryCapCentering(){var m=new Model();var c=started(m);airborneBeforeCap(m,c);m.at(safeCapCorner(),true,true);assertEquals(SupplementalWaterCoverage.State.BLOCKED,c.tick());}
 @Test void neighboringBlockBeyondCapStillBlocks(){var m=new Model();var c=started(m);airborneBeforeCap(m,c);m.at(new Vec3(55.5,71,-45.0),true,false);int writes=m.writes;assertEquals(SupplementalWaterCoverage.State.BLOCKED,c.tick());assertEquals(writes,m.writes);}
 @Test void originalPerpendicularColumnLimitStillRejectsPointNineteenCorner(){var m=new Model();var c=started(m);airborneBeforeCap(m,c);m.at(new Vec3(55.69,71,-45.31),true,false);assertEquals(SupplementalWaterCoverage.State.BLOCKED,c.tick());}
 @Test void changedPlanGeometryStillBlocksBeforeCenteringWrite(){var m=new Model();var c=started(m);airborneBeforeCap(m,c);m.at(safeCapCorner(),true,false);m.current=false;int writes=m.writes;assertEquals(SupplementalWaterCoverage.State.BLOCKED,c.tick());assertEquals(writes,m.writes);}
 @Test void centeringMovementCallbackCannotResurrectStoppedPlan(){var m=new Model();var c=started(m);airborneBeforeCap(m,c);m.at(safeCapCorner(),true,false);m.moveCallback=c::stop;assertEquals(SupplementalWaterCoverage.State.IDLE,c.tick());assertNull(c.plan());assertFalse(m.jump);assertFalse(m.attack);}
 @Test void centeringWithoutActualAirborneProofCannotEnterChannel(){var m=new Model();var c=started(m);toJump(m,c);c.tick();m.at(safeCapCorner(),true,false);assertEquals(SupplementalWaterCoverage.State.JUMP_CAP,c.tick());m.at(PLAN.capFeet(),true,false);assertEquals(SupplementalWaterCoverage.State.BLOCKED,c.tick());}

 @Test void airborneWithoutOriginalIssuedJumpCannotCenterCap(){var m=new Model();var c=started(m);toJump(m,c);m.at(new Vec3(55.5,70.5,-46.0),false,false);c.tick();assertFalse(m.jump);m.at(safeCapCorner(),true,false);int writes=m.writes;assertEquals(SupplementalWaterCoverage.State.BLOCKED,c.tick());assertEquals(writes,m.writes);assertFalse(m.jump);assertFalse(m.attack);}

 static Vec3 capturedRejectedLanding(){return new Vec3(55.41106788260305,71.0,-45.86777268015787);}
 @Test void actualCapturedGroundedLandingCentersThenUsesUnchangedArrivalCircle(){var m=new Model();var c=started(m);airborneBeforeCap(m,c);m.at(capturedRejectedLanding(),true,false);assertTrue(m.feet.horizontalDistanceTo(PLAN.capFeet())>.18);assertEquals(55,Math.floor(m.feet.x()));assertEquals(-46,Math.floor(m.feet.z()));assertEquals(SupplementalWaterCoverage.State.JUMP_CAP,c.tick());assertEquals(PLAN.capFeet(),m.target);assertFalse(m.jump);assertFalse(m.attack);m.at(PLAN.capFeet(),true,false);assertEquals(SupplementalWaterCoverage.State.ENTER_CHANNEL,c.tick());}
 @Test void groundedAlongCapEdgeContinuesOnlyTowardOriginalCenter(){var m=new Model();var c=started(m);airborneBeforeCap(m,c);m.at(new Vec3(55.5,71,-46.0),true,false);assertEquals(SupplementalWaterCoverage.State.JUMP_CAP,c.tick());assertEquals(PLAN.capFeet(),m.target);assertFalse(m.jump);assertFalse(m.attack);}
 @Test void previousNeighborAtNegativeBoundaryCannotCenter(){var m=new Model();var c=started(m);airborneBeforeCap(m,c);m.at(new Vec3(55.5,71,-46.000001),true,false);int writes=m.writes;assertEquals(SupplementalWaterCoverage.State.BLOCKED,c.tick());assertEquals(writes,m.writes);}
 @Test void capturedLandingWithCurrentBodyObstructionRefusesBeforeMovement(){var m=new Model();var c=started(m);airborneBeforeCap(m,c);m.at(capturedRejectedLanding(),true,false);m.clear=false;int writes=m.writes;assertEquals(SupplementalWaterCoverage.State.BLOCKED,c.tick());assertEquals(writes,m.writes);assertFalse(m.jump);assertFalse(m.attack);}
 @Test void capturedLandingInWaterIsNotDryCapSupport(){var m=new Model();var c=started(m);airborneBeforeCap(m,c);m.at(capturedRejectedLanding(),true,true);int writes=m.writes;assertEquals(SupplementalWaterCoverage.State.BLOCKED,c.tick());assertEquals(writes,m.writes);}
 @Test void capturedLandingAtWrongHeightRefusesBeforeMovement(){var m=new Model();var c=started(m);airborneBeforeCap(m,c);Vec3 f=capturedRejectedLanding();m.at(new Vec3(f.x(),70.9375,f.z()),true,false);int writes=m.writes;assertEquals(SupplementalWaterCoverage.State.BLOCKED,c.tick());assertEquals(writes,m.writes);}
 @Test void capturedLandingWithInvalidOriginalPlanRefusesBeforeMovement(){var m=new Model();var c=started(m);airborneBeforeCap(m,c);m.at(capturedRejectedLanding(),true,false);m.current=false;int writes=m.writes;assertEquals(SupplementalWaterCoverage.State.BLOCKED,c.tick());assertEquals(writes,m.writes);}
 @Test void capturedLandingWithoutOriginalJumpCannotCenter(){var m=new Model();var c=started(m);toJump(m,c);m.at(new Vec3(55.5,70.5,-46),false,false);c.tick();m.at(capturedRejectedLanding(),true,false);int writes=m.writes;assertEquals(SupplementalWaterCoverage.State.BLOCKED,c.tick());assertEquals(writes,m.writes);}
 @Test void capturedLandingCallbackReplacementCannotCommitOldMovement(){var m=new Model();var c=started(m);airborneBeforeCap(m,c);m.at(capturedRejectedLanding(),true,false);m.currentRead=()->{c.stop();m.at(PLAN.primaryEnd(),true,false);assertTrue(c.start(PLAN));};int writes=m.writes;assertEquals(SupplementalWaterCoverage.State.APPROACH,c.tick());assertEquals(writes,m.writes);assertSame(PLAN,c.plan());}

 static void toReturning(Model m,SupplementalWaterCoverage c){toWater(m,c);m.at(PLAN.channelFar(),true,true);c.tick();m.at(PLAN.channelNear(),true,true);c.tick();assertEquals(SupplementalWaterCoverage.State.JUMP_EXIT,c.state());c.tick();assertTrue(m.jump);m.at(PLAN.capFeet(),true,false);assertEquals(SupplementalWaterCoverage.State.RETURN_PRIMARY,c.tick());}
 static Vec3 observedDryPortal(){return new Vec3(55.502725570062275,70,-46.69999998807907);}
 @Test void originalDryPortalMayCenterWithoutClaimingApproachArrival(){var m=new Model();var c=started(m);toReturning(m,c);m.at(observedDryPortal(),true,false);assertTrue(m.feet.horizontalDistanceTo(PLAN.approachFeet())>.1);assertEquals(SupplementalWaterCoverage.State.RETURN_PRIMARY,c.tick());assertEquals(PLAN.approachFeet(),m.target);assertFalse(m.jump);assertFalse(m.attack);m.at(PLAN.approachFeet(),true,false);assertEquals(SupplementalWaterCoverage.State.RETURN_PRIMARY,c.tick());m.at(PLAN.primaryEnd(),true,false);assertEquals(SupplementalWaterCoverage.State.COMPLETE,c.tick());}
 @Test void dryPortalCannotBeAdoptedBeforeActualCapArrival(){var m=new Model();var c=started(m);toWater(m,c);m.at(PLAN.channelFar(),true,true);c.tick();m.at(PLAN.channelNear(),true,true);c.tick();c.tick();m.at(observedDryPortal(),true,false);int writes=m.writes;assertEquals(SupplementalWaterCoverage.State.BLOCKED,c.tick());assertEquals(writes,m.writes);}
 @Test void wetPortalStillRefusesOldWaterEnvelopeEscape(){var m=new Model();var c=started(m);toReturning(m,c);m.at(observedDryPortal(),true,true);int writes=m.writes;assertEquals(SupplementalWaterCoverage.State.BLOCKED,c.tick());assertEquals(writes,m.writes);}
 @Test void airbornePortalCannotCenterAsGroundedSupport(){var m=new Model();var c=started(m);toReturning(m,c);m.at(observedDryPortal(),false,false);int writes=m.writes;assertEquals(SupplementalWaterCoverage.State.BLOCKED,c.tick());assertEquals(writes,m.writes);}
 @Test void raisedFarmlandHeightCannotBorrowDryPortal(){var m=new Model();var c=started(m);toReturning(m,c);var p=observedDryPortal();m.at(new Vec3(p.x(),70.9375,p.z()),true,false);assertEquals(SupplementalWaterCoverage.State.BLOCKED,c.tick());}
 @Test void originalPerpendicularColumnPointNineteenStillRefusesPortal(){var m=new Model();var c=started(m);toReturning(m,c);m.at(new Vec3(55.69,70,-46.69999998807907),true,false);assertEquals(SupplementalWaterCoverage.State.BLOCKED,c.tick());}
 @Test void outsideExistingDryCorridorStillRefusesEvenInSameBlock(){var m=new Model();var c=started(m);toReturning(m,c);m.at(new Vec3(55.5,70,-46.706),true,false);assertEquals(SupplementalWaterCoverage.State.BLOCKED,c.tick());}
 @Test void differentPortalBlockCannotBeAdopted(){var m=new Model();var c=started(m);toReturning(m,c);m.at(new Vec3(55.5,70,-47.0001),true,false);assertEquals(SupplementalWaterCoverage.State.BLOCKED,c.tick());}
 @Test void invalidOriginalPlanBlocksBeforePortalCentering(){var m=new Model();var c=started(m);toReturning(m,c);m.at(observedDryPortal(),true,false);m.current=false;int writes=m.writes;assertEquals(SupplementalWaterCoverage.State.BLOCKED,c.tick());assertEquals(writes,m.writes);}
 @Test void nativeBodyObstructionIsNeverBypassedAtPortal(){var m=new Model();var c=started(m);toReturning(m,c);m.at(observedDryPortal(),true,false);m.clear=false;int writes=m.writes;assertEquals(SupplementalWaterCoverage.State.BLOCKED,c.tick());assertEquals(writes,m.writes);}
 @Test void originalWorldCallbackStopCannotPublishPortalKeys(){var m=new Model();var c=started(m);toReturning(m,c);m.at(observedDryPortal(),true,false);m.currentRead=c::stop;int writes=m.writes;assertEquals(SupplementalWaterCoverage.State.IDLE,c.tick());assertEquals(writes,m.writes);}
 @Test void replacementDuringPortalReadKeepsNewPlanAndPublishesNoOldMove(){var m=new Model();var c=started(m);toReturning(m,c);m.at(observedDryPortal(),true,false);m.currentRead=()->{c.stop();m.at(PLAN.primaryEnd(),true,false);assertTrue(c.start(PLAN));};int writes=m.writes;assertEquals(SupplementalWaterCoverage.State.APPROACH,c.tick());assertEquals(writes,m.writes);assertSame(PLAN,c.plan());}
 @Test void movementCallbackRetiresPortalWithoutResurrection(){var m=new Model();var c=started(m);toReturning(m,c);m.at(observedDryPortal(),true,false);m.moveCallback=c::stop;assertEquals(SupplementalWaterCoverage.State.IDLE,c.tick());assertNull(c.plan());assertFalse(m.jump||m.attack);}
 @Test void portalCenteringDoesNotResetOriginalReturnDeadline(){var m=new Model();var c=started(m);toReturning(m,c);m.at(observedDryPortal(),true,false);for(int i=0;i<160;i++)assertEquals(SupplementalWaterCoverage.State.RETURN_PRIMARY,c.tick());assertEquals(SupplementalWaterCoverage.State.BLOCKED,c.tick());assertFalse(m.jump||m.attack);}

}
